import numpy as np

def accuracy(y_true, y_pred):
    # het aandeel voorspellingen dat klopt
    return np.mean(y_true == y_pred)

def precision(y_true, y_pred):
    tp = np.sum((y_true == 1) & (y_pred == 1))
    fp = np.sum((y_true == 0) & (y_pred == 1))
    return tp / (tp + fp)

def recall(y_true, y_pred):
    tp = np.sum((y_true == 1) & (y_pred == 1))
    fn = np.sum((y_true == 1) & (y_pred == 0))
    return tp / (tp + fn)

def f1(y_true, y_pred):
    p = precision(y_true, y_pred)
    r = recall(y_true, y_pred)
    return 2 * p * r / (p + r)

# voorbeeld: 10 voorspellingen
y_true = np.array([1, 0, 1, 1, 0, 0, 1, 0, 1, 1])
y_pred = np.array([1, 1, 0, 1, 0, 1, 1, 0, 1, 0])

# TP=4, FP=2, TN=2, FN=2
print('accuracy :', accuracy(y_true, y_pred))   # 0.6
print('precision:', precision(y_true, y_pred))  # 0.6666666666666666
print('recall   :', recall(y_true, y_pred))     # 0.6666666666666666
print('f1       :', f1(y_true, y_pred))         # 0.6666666666666666
